"""Minimal append-only reality ledger, hypothesis registry, and bottleneck cycle."""
from __future__ import annotations
import hashlib, json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

EVIDENCE_CLASSES = {"SIMULATED", "SYNTHETIC", "DERIVED", "REAL_INTERNAL", "REAL_EXTERNAL_ACTION", "INDEPENDENT_EXTERNAL"}
INDEPENDENCE = {"OMEGA", "OWNER", "THIRD_PARTY", "UNKNOWN"}
VALUE_LEVELS = {f"L{i}" for i in range(7)}

def _now(): return datetime.now(timezone.utc).isoformat(timespec="seconds")
def _write(path, value):
    path.parent.mkdir(parents=True, exist_ok=True); path.write_text(json.dumps(value, ensure_ascii=False, indent=2)+"\n", encoding="utf-8")

def validate_reality_event(event: dict[str, Any]) -> dict[str, Any]:
    required={"event_id","timestamp","actor","branch","action","source","evidence_class","independence_class","value_level","verification_status"}
    missing=sorted(required-set(event)); errors=[]
    if event.get("evidence_class") not in EVIDENCE_CLASSES: errors.append("invalid_evidence_class")
    if event.get("independence_class") not in INDEPENDENCE: errors.append("invalid_independence_class")
    if event.get("value_level") not in VALUE_LEVELS: errors.append("invalid_value_level")
    if event.get("value_level") != "L0" and event.get("independence_class") != "THIRD_PARTY" and event.get("evidence_class") != "INDEPENDENT_EXTERNAL": errors.append("unsupported_promotion")
    return {"valid": not missing and not errors, "missing": missing, "errors": errors, "event": event}

def append_reality_event(root: Path, event: dict[str, Any]) -> dict[str, Any]:
    check=validate_reality_event(event)
    if not check["valid"]: raise ValueError("CLAIM_REJECTED:"+",".join(check["missing"]+check["errors"]))
    path=root/".omega"/"zero"/"reality_ledger.jsonl"; path.parent.mkdir(parents=True,exist_ok=True)
    with path.open("a",encoding="utf-8") as stream: stream.write(json.dumps(event,ensure_ascii=False,sort_keys=True)+"\n")
    return event

def ingest_current_reality(root: Path) -> list[dict[str, Any]]:
    now=_now(); base=[
      ("e2-sends","e2-01","four one-to-one Gmail messages accepted; delivery/replies zero","REAL_EXTERNAL_ACTION","OWNER","L0","VERIFIED"),
      ("gmail-channel","e2-01","Gmail OAuth/channel readiness verified","REAL_INTERNAL","OMEGA","L0","VERIFIED"),
      ("github-publication","zero-inbound-001","privacy-safe public artifact published and verified","REAL_EXTERNAL_ACTION","OWNER","L0","VERIFIED"),
      ("metadata-publication","zero-discovery-001","public description/topics metadata updated","REAL_EXTERNAL_ACTION","OWNER","L0","VERIFIED"),
      ("zero-inbound","inbound-evidence","published artifact awaiting independent installation","DERIVED","OMEGA","L0","VERIFIED"),
      ("zero-discovery","zero-discovery-001","metadata action produced no discovery signal","DERIVED","OMEGA","L0","VERIFIED"),
      ("zero-value-bridge","zero-economic-bridge-001","CI receipt experiment frozen awaiting independent consumption","DERIVED","OMEGA","L0","VERIFIED"),
      ("wo-comment","zero-counterparty-work-order-001","one public technical comment; no response","REAL_EXTERNAL_ACTION","OWNER","L0","VERIFIED"),
      ("preb","provider-resilience","quota checkpoint/recovery simulation passed","SIMULATED","OMEGA","L0","VERIFIED"),
      ("v030","v0.30","external evaluator evidence still waiting","DERIVED","OMEGA","L0","VERIFIED"),
      ("zeu","zeu","internal settlement simulations only","SIMULATED","OMEGA","L0","VERIFIED"),
      ("economic-value","global","real economic value remains zero KWD","REAL_INTERNAL","OMEGA","L0","VERIFIED"),]
    events=[]
    for eid,branch,action,klass,ind,level,status in base:
        event={"event_id":eid,"timestamp":now,"actor":"OMEGA","counterparty":None,"branch":branch,"action":action,"artifact_refs":[],"source":"repository state","evidence_class":klass,"independence_class":ind,"value_level":level,"utility_state":"UNKNOWN","causality_state":"UNKNOWN","economic_state":"0_KWD","confidence":"HIGH" if status=="VERIFIED" else "UNKNOWN","contradictions":[],"freshness":"CURRENT","verification_status":status}
        events.append(event); append_reality_event(root,event)
    return events

