    result={"cycle_id":"zbi-cycle-0001","state":"OPERATED","failures":failures,"bottlenecks":bottlenecks,"dominant_bottleneck":winner,"red":red,"removal_options":options,"shadow_prices":{"independent_evidence_acquisition":{"index":1.0,"unit":"relative","is_money":False},"counterparty_access":{"index":.72,"unit":"relative","is_money":False},"host_execution":{"index":.18,"unit":"relative","is_money":False},"ai_reasoning":{"index":.55,"unit":"relative","is_money":False}},"capability_roi_options":[{"id":"independent-evaluator","acquisition_cost":"external authority","actions_unlocked":["L1-L4"],"expected_lifetime_usefulness":"HIGH","roi":"UNKNOWN"}],"action_executed":"wait-existing-response","global_state":"RUNNING","current_value_level":"L0","real_economic_value_kwd":0,"wo_zero_state":"PROPOSED_WORK_ORDER/PARKED_WAITING_EXTERNAL/NO_RESPONSE"}
    out=root/".omega"/"zero"; _write(out/"reality_cycle_0001.json",result); _write(out/"reality_ledger_snapshot.json",events); _write(out/"failure_cartography.json",failures); _write(out/"bottleneck_cycle_0001.json",result); return result


